typedef struct { const char* name; const char* data; size_t len; } Entry;
static const Entry table[] = {
    { "pulse_drive.frgl", SONG_PULSE_DRIVE, sizeof(SONG_PULSE_DRIVE) - 1 },
    { "crystal_cascade.frgl", SONG_CRYSTAL_CASCADE, sizeof(SONG_CRYSTAL_CASCADE) - 1 },
    { "neon_heartbeat.frgl", SONG_NEON_HEARTBEAT, sizeof(SONG_NEON_HEARTBEAT) - 1 },
    { "glitch_garden.frgl", SONG_GLITCH_GARDEN, sizeof(SONG_GLITCH_GARDEN) - 1 },
};

bool builtin_song_lookup(const char* name, const char** data, size_t* len) {
    for(size_t i = 0; i < sizeof(table)/sizeof(table[0]); i++) {
        if(strcmp(name, table[i].name) == 0) {
            *data = table[i].data;
            *len  = table[i].len;
            return true;
        }
    }
    return false;
}
